-------------------------------------------------------------------------------
-- - ItemSize()
-- - SameLine()
-- - GetCursorScreenPos()
-- - SetCursorScreenPos()
-- - GetCursorPos(), GetCursorPosX(), GetCursorPosY()
-- - SetCursorPos(), SetCursorPosX(), SetCursorPosY()
-- - GetCursorStartPos()
-- - Indent()
-- - Unindent()
-- - SetNextItemWidth()
-- - PushItemWidth()
-- - PushMultiItemsWidths()
-- - PopItemWidth()
-- - CalcItemWidth()
-- - CalcItemSize()
-- - GetTextLineHeight()
-- - GetTextLineHeightWithSpacing()
-- - GetFrameHeight()
-- - GetFrameHeightWithSpacing()
