function ImGui.SetNextWindowBgAlpha(alpha)
    local g = GImGui
    g.NextWindowData.HasFlags = bit32.bor(g.NextWindowData.HasFlags, ImGuiNextWindowDataFlags.HasBgAlpha)
    g.NextWindowData.BgAlphaVal = alpha
end

