-- Get desired mouse cursor shape.
-- Important: this is meant to be used by a platform backend, it is reset in ImGui.NewFrame(),
-- updated during the frame, and locked in EndFrame()/Render().
-- If you use software rendering by setting io.MouseDrawCursor then Dear ImGui will render those for you
function ImGui.GetMouseCursor()
    local g = GImGui
    return g.MouseCursor
end

-- We intentionally accept values of ImGuiMouseCursor that are outside our bounds, in case users needs to hack-in a custom cursor value.
-- Custom cursors may be handled by custom backends. If you are using a standard backend and want to hack in a custom cursor, you may
-- handle it before the backend _NewFrame() call and temporarily set ImGuiConfigFlags.NoMouseCursorChange during the backend _NewFrame() call.
--- @param cursor_type ImGuiMouseCursor
function ImGui.SetMouseCursor(cursor_type)
    local g = GImGui
    g.MouseCursor = cursor_type
end

-------------------------------------------------------------------------------
-- [SECTION] MISC HELPERS/UTILITIES (Color functions)
-- Note: The Convert functions are early design which are not consistent with other API.
-------------------------------------------------------------------------------

--- @param col_a ImU32
--- @param col_b ImU32
--- @return ImU32
function ImStd.ImAlphaBlendColors(col_a, col_b)
    local t = bit32.band(bit32.rshift(col_b, IM_COL32_A_SHIFT), 0xFF) / 255.0
    local r = ImLerp(bit32.band(bit32.rshift(col_a, IM_COL32_R_SHIFT), 0xFF), bit32.band(bit32.rshift(col_b, IM_COL32_R_SHIFT), 0xFF), t)
    local g = ImLerp(bit32.band(bit32.rshift(col_a, IM_COL32_G_SHIFT), 0xFF), bit32.band(bit32.rshift(col_b, IM_COL32_G_SHIFT), 0xFF), t)
    local b = ImLerp(bit32.band(bit32.rshift(col_a, IM_COL32_B_SHIFT), 0xFF), bit32.band(bit32.rshift(col_b, IM_COL32_B_SHIFT), 0xFF), t)
    return IM_COL32(r, g, b, 0xFF)
end

--- @param in_col  ImU32
--- @param out_col ImVec4?
--- @return ImVec4?
function ImGui.ColorConvertU32ToFloat4(in_col, out_col)
    local s = 1.0 / 255.0
    local r = bit32.band(bit32.rshift(in_col, IM_COL32_R_SHIFT), 0xFF) * s
    local g = bit32.band(bit32.rshift(in_col, IM_COL32_G_SHIFT), 0xFF) * s
    local b = bit32.band(bit32.rshift(in_col, IM_COL32_B_SHIFT), 0xFF) * s
    local a = bit32.band(bit32.rshift(in_col, IM_COL32_A_SHIFT), 0xFF) * s

    if out_col then
        out_col[1] = r; out_col[2] = g; out_col[3] = b; out_col[4] = a
    else
        return ImVec4(r, g, b, a)
    end
end

--- @param in_col ImVec4
--- @return ImU32
local function F32ToU8Sat(v) if v < 0.0 then v = 0.0 elseif v > 1.0 then v = 1.0 end return math.floor(v * 255.0 + 0.5) end

@native
function ImGui.ColorConvertFloat4ToU32(in_col)
    return bit32.bor(F32ToU8Sat(in_col.x), bit32.lshift(F32ToU8Sat(in_col.y), 8), bit32.lshift(F32ToU8Sat(in_col.z), 16), bit32.lshift(F32ToU8Sat(in_col.w), 24))
end

-- Convert rgb floats ([0-1],[0-1],[0-1]) to hsv floats ([0-1],[0-1],[0-1]), from Foley & van Dam p592
-- Optimized http://lolengine.net/blog/2013/01/13/fast-rgb-to-hsv
--- @param r float
--- @param g float
--- @param b float
--- @return float, float, float
@native
function ImGui.ColorConvertRGBtoHSV(r, g, b)
    local K = 0.0
    if g < b then
        g, b = b, g
        K = -1.0
    end
    if r < g then
        r, g = g, r
        K = -2.0 / 6.0 - K
    end

    local chroma = r - (g < b and g or b)
    local out_h = ImFabs(K + (g - b) / (6.0 * chroma + 1e-20))
    local out_s = chroma / (r + 1e-20)
    local out_v = r
    return out_h, out_s, out_v
end

-- Convert hsv floats ([0-1],[0-1],[0-1]) to rgb floats ([0-1],[0-1],[0-1]), from Foley & van Dam p593
-- also http://en.wikipedia.org/wiki/HSL_and_HSV
--- @param h float
--- @param s float
--- @param v float
--- @return float, float, float
@native
function ImGui.ColorConvertHSVtoRGB(h, s, v)
    if s == 0.0 then
        -- gray
        return v, v, v
    end

    h = ImFmod(h, 1.0) / (60.0 / 360.0)
    local i = math.floor(h)
    local f = h - i
    local p = v * (1.0 - s)
    local q = v * (1.0 - s * f)
    local t = v * (1.0 - s * (1.0 - f))

    if i == 0 then
        return v, t, p
    elseif i == 1 then
        return q, v, p
    elseif i == 2 then
        return p, v, t
    elseif i == 3 then
        return p, q, v
    elseif i == 4 then
        return t, p, v
    else -- [Port] i == 5 or default
        return v, p, q
    end
end

-- Generic helper, equivalent to old ImGui.CalcListClipping() but stateless
--- @param clip_rect    ImRect
--- @param pos          ImVec2
--- @param items_height float
function ImGui.CalcClipRectVisibleItemsY(clip_rect, pos, items_height)
    -- [Port] returns (out_visible_start, out_visible_end), 0-based like upstream
    local out_visible_start = ImMax(ImTrunc((clip_rect.Min.y - pos.y) / items_height), 0)
    local out_visible_end = ImMax(ImTrunc(ImCeil((clip_rect.Max.y - pos.y) / items_height)), out_visible_start)
    return out_visible_start, out_visible_end
end

