--- @param entries ImGuiLocEntry[]
--- @param count   int
function ImGui.LocalizeRegisterEntries(entries, count)
    local g = GImGui
    for n = 1, count do
        g.LocalizationTable[entries[n].Key] = entries[n].Text
    end
end

