-- [SECTION] Font atlas / font debugging
-------------------------------------------------------------------------------

-- [Port] byte buffers for InputText (same as the demo's DemoBuf/DemoBufStr; kept here so the library doesn't need the demo)
local function DemoBuf(str, size)
    local t = {}
    for i = 1, #str do t[i] = string.byte(str, i) end
    t[#str + 1] = 0
    if size then for i = #str + 2, size do t[i] = 0 end end
    return t
end
local function DemoBufStr(buf)
    local n = 0
    while buf[n + 1] ~= nil and buf[n + 1] ~= 0 do n = n + 1 end
    if n == 0 then return "" end
    return ImGui._ByteArrayToString(buf, 1, n + 1)
end

-- Avoid naming collision with imgui_demo's HelpMarker() for unity builds.
local function MetricsHelpMarker(desc)
    ImGui.TextDisabled("(?)")
    if ImGui.BeginItemTooltip() then
        ImGui.PushTextWrapPos(ImGui.GetFontSize() * 35.0)
        ImGui.TextUnformatted(desc)
        ImGui.PopTextWrapPos()
        ImGui.EndTooltip()
    end
end
ImGui.MetricsHelpMarker = MetricsHelpMarker

local function U8(c) return (c and c > 0) and utf8.char(c) or "" end

-- [Luau] table.sort() "less than" predicate (upstream: ImQsort() comparer returning b - a)
--- @param a ImGuiViewportP
--- @param b ImGuiViewportP
local function ViewportComparerByLastFocusedStampCount(a, b)
    return b.LastFocusedStampCount < a.LastFocusedStampCount
end

-- Draw an arbitrary US keyboard layout to visualize translated keys
--- @param draw_list ImDrawList
function ImGui.DebugRenderKeyboardPreview(draw_list)
    local scale = ImGui.GetFontSize() / 13.0
    local key_size = ImVec2(35.0, 35.0) * scale
    local key_rounding = 3.0 * scale
    local key_face_size = ImVec2(25.0, 25.0) * scale
    local key_face_pos = ImVec2(5.0, 3.0) * scale
    local key_face_rounding = 2.0 * scale
    local key_label_pos = ImVec2(7.0, 4.0) * scale
    local key_step = ImVec2(key_size.x - 1.0, key_size.y - 1.0)
    local key_row_offset = 9.0 * scale

    local board_min = ImGui.GetCursorScreenPos()
    local board_max = ImVec2(board_min.x + 3 * key_step.x + 2 * key_row_offset + 10.0, board_min.y + 3 * key_step.y + 10.0)
    local start_pos = ImVec2(board_min.x + 5.0 - key_step.x, board_min.y)

    local K = ImGuiKey
    local keys_to_display = { -- [Port] { Row, Col, Label, Key }
        { 0, 0, "", K.Tab },       { 0, 1, "Q", K.Q }, { 0, 2, "W", K.W }, { 0, 3, "E", K.E }, { 0, 4, "R", K.R },
        { 1, 0, "", K.CapsLock },  { 1, 1, "A", K.A }, { 1, 2, "S", K.S }, { 1, 3, "D", K.D }, { 1, 4, "F", K.F },
        { 2, 0, "", K.LeftShift }, { 2, 1, "Z", K.Z }, { 2, 2, "X", K.X }, { 2, 3, "C", K.C }, { 2, 4, "V", K.V },
    }

    -- Elements rendered manually via ImDrawList API are not clipped automatically.
    -- While not strictly necessary, here IsItemVisible() is used to avoid rendering these shapes when they are out of view.
    ImGui.Dummy(board_max - board_min)
    if not ImGui.IsItemVisible() then
        return
    end
    draw_list:PushClipRect(board_min, board_max, true)
    for n = 1, #keys_to_display do
        local key_data = keys_to_display[n]
        local key_min = ImVec2(start_pos.x + key_data[2] * key_step.x + key_data[1] * key_row_offset, start_pos.y + key_data[1] * key_step.y)
        local key_max = key_min + key_size
        draw_list:AddRectFilled(key_min, key_max, IM_COL32(204, 204, 204, 255), key_rounding)
        draw_list:AddRect(key_min, key_max, IM_COL32(24, 24, 24, 255), key_rounding)
        local face_min = ImVec2(key_min.x + key_face_pos.x, key_min.y + key_face_pos.y)
        local face_max = ImVec2(face_min.x + key_face_size.x, face_min.y + key_face_size.y)
        draw_list:AddRect(face_min, face_max, IM_COL32(193, 193, 193, 255), key_face_rounding, 2.0)
        draw_list:AddRectFilled(face_min, face_max, IM_COL32(252, 252, 252, 255), key_face_rounding)
        local label_min = ImVec2(key_min.x + key_label_pos.x, key_min.y + key_label_pos.y)
        draw_list:AddText(label_min, IM_COL32(64, 64, 64, 255), key_data[3])
        if ImGui.IsKeyDown(key_data[4]) then
            draw_list:AddRectFilled(key_min, key_max, IM_COL32(255, 0, 0, 128), key_rounding)
        end
    end
    draw_list:PopClipRect()
end

local function DebugFlashStyleColorStop()
    local g = GImGui
    if g.DebugFlashStyleColorIdx ~= ImGuiCol.COUNT then
        ImVec4_Copy(g.Style.Colors[g.DebugFlashStyleColorIdx], g.DebugFlashStyleColorBackup)
    end
    g.DebugFlashStyleColorIdx = ImGuiCol.COUNT
end

-- Flash a given style color for some + inhibit modifications of this color via PushStyleColor() calls.
--- @param idx ImGuiCol
function ImGui.DebugFlashStyleColor(idx)
    local g = GImGui
    DebugFlashStyleColorStop()
    g.DebugFlashStyleColorTime = 0.5
    g.DebugFlashStyleColorIdx = idx
    ImVec4_Copy(g.DebugFlashStyleColorBackup, g.Style.Colors[idx])
end

function ImGui.UpdateDebugToolFlashStyleColor()
    local g = GImGui
    if g.DebugFlashStyleColorTime <= 0.0 then
        return
    end
    local col = g.Style.Colors[g.DebugFlashStyleColorIdx]
    col.x, col.y, col.z = ImGui.ColorConvertHSVtoRGB(math.cos(g.DebugFlashStyleColorTime * 6.0) * 0.5 + 0.5, 0.5, 0.5)
    col.w = 1.0
    g.DebugFlashStyleColorTime = g.DebugFlashStyleColorTime - g.IO.DeltaTime
    if g.DebugFlashStyleColorTime <= 0.0 then
        DebugFlashStyleColorStop()
    end
end

-- [Luau] ImTextureID can be any Lua value here: numbers are returned as is, anything else is returned unchanged too
-- (there is no memcpy into an ImU64); FormatTextureRefForDebugDisplay() formats non-numbers with tostring().
--- @param tex_id ImTextureID
function ImGui.DebugTextureIDToU64(tex_id)
    return tex_id
end

--- @param tex_ref ImTextureRef
--- @return string
local function FormatTextureRefForDebugDisplay(tex_ref)
    local buf = ""
    if tex_ref._TexData ~= nil then
        buf = string.format("#%03d: ", tex_ref._TexData.UniqueID)
    end
    local v = ImGui.DebugTextureIDToU64(tex_ref:GetTexID())
    if type(v) == "number" and v >= 0 and v == math.floor(v) then
        return buf .. string.format("0x%X", v)
    end
    return buf .. tostring(v)
end

-- Demo helper function to select among loaded fonts.
-- Here we use the regular BeginCombo()/EndCombo() api which is the more flexible one.
function ImGui.ShowFontSelector(label)
    local io = ImGui.GetIO()
    local font_current = ImGui.GetFont()
    if ImGui.BeginCombo(label, font_current:GetDebugName()) then
        for i, font in io.Fonts.Fonts:iter() do
            ImGui.PushID(i)
            if ImGui.Selectable(font:GetDebugName(), font == font_current, ImGuiSelectableFlags.SelectOnNav) then io.FontDefault = font end
            if font == font_current then ImGui.SetItemDefaultFocus() end
            ImGui.PopID()
        end
        ImGui.EndCombo()
    end
    ImGui.SameLine()
    MetricsHelpMarker("- Load additional fonts with io.Fonts->AddFontXXX() functions.\n- On Roblox: register the .ttf bytes with ImGui_ImplRoblox.AddFile() first.\n- Read FAQ and docs/FONTS.md for more details.")
end

function ImGui.DebugNodeFontGlyph(font, glyph)
    ImGui.Text("Codepoint: U+%04X", glyph.Codepoint)
    ImGui.Separator()
    ImGui.Text("Visible: %d", glyph.Visible and 1 or 0)
    ImGui.Text("AdvanceX: %.1f", glyph.AdvanceX)
    ImGui.Text("Pos: (%.2f,%.2f)->(%.2f,%.2f)", glyph.X0, glyph.Y0, glyph.X1, glyph.Y1)
    ImGui.Text("UV: (%.3f,%.3f)->(%.3f,%.3f)", glyph.U0, glyph.V0, glyph.U1, glyph.V1)
    if glyph.PackId >= 0 then
        local r = { uv0 = ImVec2(), uv1 = ImVec2() }
        if font.OwnerAtlas:GetCustomRect(glyph.PackId, r) then ImGui.Text("PackId: 0x%X (%dx%d rect at %d,%d)", glyph.PackId, r.w, r.h, r.x, r.y) end
    end
    ImGui.Text("SourceIdx: %d", glyph.SourceIdx)
end

function ImGui.DebugNodeFontGlyphsForSrcMask(font, baked, src_mask)
    local draw_list = ImGui.GetWindowDrawList()
    local glyph_col = ImGui.GetColorU32(ImGuiCol.Text)
    local cell_size = baked.Size * 1
    local cell_spacing = ImGui.GetStyle().ItemSpacing.y
    -- [Port] only scans loaded codepoints (IndexLookup range) instead of the whole 0..0xFFFF range
    local max_c = baked.IndexLookup.Size - 1
    local base = 0
    while base <= max_c do
        local count = 0
        -- [Luau] inline IsGlyphLoaded() + FindGlyphNoFallback() (a loaded glyph never needs loading): 0xFFFF = IM_FONTGLYPH_INDEX_UNUSED, 0xFFFE = IM_FONTGLYPH_INDEX_NOT_FOUND
        local lookup, lookup_n, glyphs = baked.IndexLookup.Data, baked.IndexLookup.Size, baked.Glyphs.Data
        for n = 0, 255 do
            local c = base + n
            if c < lookup_n then
                local i = lookup[c + 1]
                if i ~= 0xFFFF and i ~= 0xFFFE then
                    local glyph = glyphs[i]
                    if glyph and bit32.band(src_mask, bit32.lshift(1, glyph.SourceIdx)) ~= 0 then count = count + 1 end
                end
            end
        end
        if count > 0 and ImGui.TreeNode(base, "U+%04X..U+%04X (%d %s)", base, base + 255, count, (count > 1) and "glyphs" or "glyph") then
            -- Draw a 16x16 grid of glyphs
            local base_pos = ImGui.GetCursorScreenPos()
            local cell_p1, cell_p2 = ImVec2(), ImVec2()
            for n = 0, 255 do
                local c = base + n
                -- We use ImFont:RenderChar as a shortcut because we don't have UTF-8 conversion functions
                -- available here and thus cannot easily generate a zero-terminated UTF-8 encoded string.
                -- [Luau] reused per cell: AddRect()/RenderChar()/IsMouseHoveringRect() only read them
                cell_p1.x = base_pos.x + (n % 16) * (cell_size + cell_spacing); cell_p1.y = base_pos.y + math.floor(n / 16) * (cell_size + cell_spacing)
                cell_p2.x = cell_p1.x + cell_size; cell_p2.y = cell_p1.y + cell_size
                local glyph = nil -- [Luau] inline IsGlyphLoaded() + FindGlyphNoFallback(), see above
                if c < baked.IndexLookup.Size then
                    local i = baked.IndexLookup.Data[c + 1]
                    if i ~= 0xFFFF and i ~= 0xFFFE then glyph = baked.Glyphs.Data[i] end
                end
                draw_list:AddRect(cell_p1, cell_p2, glyph and IM_COL32(255, 255, 255, 100) or IM_COL32(255, 255, 255, 50))
                if glyph and bit32.band(src_mask, bit32.lshift(1, glyph.SourceIdx)) ~= 0 then
                    font:RenderChar(draw_list, cell_size, cell_p1, glyph_col, c)
                    if ImGui.IsMouseHoveringRect(cell_p1, cell_p2) and ImGui.BeginTooltip() then
                        ImGui.DebugNodeFontGlyph(font, glyph)
                        ImGui.EndTooltip()
                    end
                end
            end
            ImGui.Dummy(ImVec2((cell_size + cell_spacing) * 16, (cell_size + cell_spacing) * 16))
            ImGui.TreePop()
        end
        base = base + 256
    end
end

-- [DEBUG] Display details for a single font, called by ShowStyleEditor().
-- [DEBUG] Compute mask of inputs with the same codepoint.
-- [Luau] the port's font loaders expose FontSrcContainsGlyph() (pre-1.93 loader API) instead of FontSrcGetGlyphIndexFromCodepoint() != 0.
local function CalcFontGlyphSrcOverlapMask(atlas, font, codepoint)
    local mask, count = 0, 0
    for src_n = 0, font.Sources.Size - 1 do repeat
        local src = font.Sources.Data[src_n + 1]
        local loader = src.FontLoader or atlas.FontLoader
        if not (loader.FontSrcContainsGlyph ~= nil and loader.FontSrcContainsGlyph(atlas, src, codepoint)) then
            break -- [Port] continue
        end
        mask = bit32.bor(mask, bit32.lshift(1, src_n))
        count = count + 1
    until true end
    return (count > 1) and mask or 0
end

function ImGui.DebugNodeFont(font)
    local g = ImGui.GetCurrentContext()
    local cfg = g.DebugMetricsConfig
    local atlas = font.OwnerAtlas
    local opened = ImGui.TreeNode(tostring(font), "Font: \"%s\": %d sources(s)", font:GetDebugName(), font.Sources.Size)

    -- Display preview text
    if not opened then ImGui.Indent() end
    ImGui.Indent()
    if cfg.ShowFontPreview then
        ImGui.PushFont(font, 0.0)
        ImGui.Text("The quick brown fox jumps over the lazy dog")
        ImGui.PopFont()
    end
    if not opened then
        ImGui.Unindent()
        ImGui.Unindent()
        return
    end
    if ImGui.SmallButton("Set as default") then ImGui.GetIO().FontDefault = font end
    ImGui.SameLine()
    ImGui.BeginDisabled(atlas.Fonts.Size <= 1 or atlas.Locked == true or atlas.RemoveFont == nil)
    if ImGui.SmallButton("Remove") and atlas.RemoveFont then atlas:RemoveFont(font) end
    ImGui.EndDisabled()
    ImGui.SameLine()
    if ImGui.SmallButton("Clear bakes") then ImFontAtlasFontDiscardBakes(atlas, font, 0) end
    ImGui.SameLine()
    if ImGui.SmallButton("Clear unused") then ImFontAtlasFontDiscardBakes(atlas, font, 2) end

    -- Display details
    ImGui.Text("Fallback character: '%s' (U+%04X)", U8(font.FallbackChar), font.FallbackChar or 0)
    ImGui.Text("Ellipsis character: '%s' (U+%04X)", U8(font.EllipsisChar), font.EllipsisChar or 0)
    for src_n, src in font.Sources:iter() do
        if ImGui.TreeNode(tostring(src), "Input %d: '%s' [%d], Oversample: %d,%d, PixelSnapH: %d, Offset: (%.1f,%.1f)",
            src_n - 1, src.Name or "", src.FontNo or 0, src.OversampleH or 0, src.OversampleV or 0, src.PixelSnapH and 1 or 0, src.GlyphOffset.x, src.GlyphOffset.y) then
            local loader = src.FontLoader or atlas.FontLoader
            ImGui.Text("Loader: '%s'", (loader and loader.Name) or "N/A")

            -- if ImGui.DragFloat("ExtraSizeScale", src.ExtraSizeScale, 0.01, 0.10, 2.0) then
            --     ImFontAtlasFontRebuildOutput(atlas, font)
            -- end
            ImGui.TreePop()
        end
    end
    if font.Sources.Size > 1 and ImGui.TreeNode("Input Glyphs Overlap Detection Tool") then
        ImGui.TextWrapped("- First Input that contains the glyph is used.\n" ..
            "- Use ImFontConfig::GlyphExcludeRanges[] to specify ranges to ignore glyph in given Input.\n- Prefer using a small number of ranges as the list is scanned every time a new glyph is loaded,\n  - e.g. GlyphExcludeRanges[] = { ICON_MIN_FA, ICON_MAX_FA, 0 };\n- This tool doesn't cache results and is slow, don't keep it open!")
        if ImGui.BeginTable("table", 2) then
            local c = 0
            while c < 0x10000 do
                local overlap_mask = CalcFontGlyphSrcOverlapMask(atlas, font, c)
                if overlap_mask ~= 0 then
                    local c_end = c + 1
                    while c_end < 0x10000 and CalcFontGlyphSrcOverlapMask(atlas, font, c_end) == overlap_mask do
                        c_end = c_end + 1
                    end
                    if ImGui.TableNextColumn() and ImGui.TreeNode(c, "U+%04X-U+%04X: %d codepoints in %d inputs", c, c_end - 1, c_end - c, ImCountSetBits(overlap_mask)) then
                        for n = c, c_end - 1 do
                            ImGui.BulletText("Codepoint U+%04X (%s)", n, U8(n))
                        end
                        ImGui.TreePop()
                    end
                    ImGui.TableNextColumn()
                    for src_n = 0, font.Sources.Size - 1 do
                        if bit32.band(overlap_mask, bit32.lshift(1, src_n)) ~= 0 then
                            ImGui.Text("%d ", src_n)
                            ImGui.SameLine()
                        end
                    end
                    c = c_end - 1
                end
                c = c + 1
            end
            ImGui.EndTable()
        end
        ImGui.TreePop()
    end

    -- Display all glyphs of the fonts in separate pages of 256 characters
    local builder = atlas.Builder
    if builder then
        for _, baked in builder.BakedPool:iter() do
            if baked.OwnerFont == font then
                ImGui.PushID(baked.BakedId)
                if ImGui.TreeNode("Glyphs", "Baked at { %.2fpx, d.%.2f }: %d glyphs%s", baked.Size, baked.RasterizerDensity, baked.Glyphs.Size,
                    (baked.LastUsedFrame < (builder.FrameCount or 0) - 1) and " *Unused*" or "") then
                    if ImGui.SmallButton("Load all") then
                        for c = 0, 0x7F do baked:FindGlyph(c) end -- [Port] ASCII only: loading the whole BMP in Luau stalls for seconds
                    end
                    local surface_sqrt = math.floor(math.sqrt(baked.MetricsTotalSurface))
                    ImGui.Text("Ascent: %f, Descent: %f, Ascent-Descent: %f", baked.Ascent, baked.Descent, baked.Ascent - baked.Descent)
                    ImGui.Text("Texture Area: about %d px ~%dx%d px", baked.MetricsTotalSurface, surface_sqrt, surface_sqrt)
                    for src_n, src in font.Sources:iter() do
                        ImGui.BulletText("Input %d: '%s', Oversample: (%d,%d), PixelSnapH: %d, Offset: (%.1f,%.1f)",
                            src_n - 1, src.Name or "", src.OversampleH or 0, src.OversampleV or 0, src.PixelSnapH and 1 or 0, src.GlyphOffset.x, src.GlyphOffset.y)
                    end
                    ImGui.DebugNodeFontGlyphsForSrcMask(font, baked, bit32.bnot(0))
                    ImGui.TreePop()
                end
                ImGui.PopID()
            end
        end
    end
    ImGui.TreePop()
    ImGui.Unindent()
end

local StatusNames = { [0] = "OK", "Destroyed", "WantCreate", "WantUpdates", "WantDestroy" }
local FormatNames = { [0] = "RGBA32", "Alpha8" }

function ImGui.DebugNodeTexture(tex, int_id, highlight_rect)
    local g = ImGui.GetCurrentContext()
    ImGui.PushID(int_id)
    if ImGui.TreeNode("", "Texture #%03d (%dx%d pixels)", tex.UniqueID or 0, tex.Width, tex.Height) then
        local cfg = g.DebugMetricsConfig
        _, cfg.ShowTextureUsedRect = ImGui.Checkbox("Show used rect", cfg.ShowTextureUsedRect)
        ImGui.PushStyleVar(ImGuiStyleVar.ImageBorderSize, math.max(1.0, g.Style.ImageBorderSize))
        local p = ImGui.GetCursorScreenPos()
        if tex.Status == ImTextureStatus.WantDestroy or tex.Status == ImTextureStatus.Destroyed then
            ImGui.Dummy(ImVec2(tex.Width, tex.Height))
        else
            local ref = ImTextureRef(); ref._TexData = tex
            ImGui.ImageWithBg(ref, ImVec2(tex.Width, tex.Height), ImVec2(0.0, 0.0), ImVec2(1.0, 1.0), ImVec4(0.0, 0.0, 0.0, 1.0))
        end
        if cfg.ShowTextureUsedRect and tex.UsedRect then
            local u = tex.UsedRect
            ImGui.GetWindowDrawList():AddRect(ImVec2(p.x + u.x, p.y + u.y), ImVec2(p.x + u.x + u.w, p.y + u.y + u.h), IM_COL32(255, 0, 255, 255))
        end
        if highlight_rect ~= nil then
            local r_outer = ImRect(p.x, p.y, p.x + tex.Width, p.y + tex.Height)
            local r_inner = ImRect(p.x + highlight_rect.x, p.y + highlight_rect.y, p.x + highlight_rect.x + highlight_rect.w, p.y + highlight_rect.y + highlight_rect.h)
            ImGui.RenderRectFilledWithHole(ImGui.GetWindowDrawList(), r_outer, r_inner, IM_COL32(0, 0, 0, 100), 0.0)
            ImGui.GetWindowDrawList():AddRect(r_inner.Min - ImVec2(1, 1), r_inner.Max + ImVec2(1, 1), IM_COL32(255, 255, 0, 255))
        end
        ImGui.PopStyleVar()
        ImGui.Text("Status = %s (%d), Format = %s (%d), UseColors = %d", StatusNames[tex.Status] or "?", tex.Status, FormatNames[tex.Format] or "?", tex.Format, tex.UseColors and 1 or 0)
        ImGui.Text("TexRef = %s, BackendUserData = %s", FormatTextureRefForDebugDisplay(tex:GetTexRef()), tostring(tex.BackendUserData))
        ImGui.TreePop()
    end
    ImGui.PopID()
end

-- [DEBUG] List fonts in a font atlas and display its texture
function ImGui.ShowFontAtlas(atlas)
    local g = ImGui.GetCurrentContext()
    local io = g.IO
    local style = g.Style
    ImGui.BeginDisabled()
    ImGui.CheckboxFlags("io.BackendFlags: RendererHasTextures", io.BackendFlags, ImGuiBackendFlags.RendererHasTextures)
    ImGui.EndDisabled()
    ImGui.ShowFontSelector("Font")
    local changed
    style.FontSizeBase, changed = ImGui.DragFloat("FontSizeBase", style.FontSizeBase, 0.20, 5.0, 100.0, "%.0f")
    if changed then style._NextFrameFontSizeBase = style.FontSizeBase end -- FIXME: Temporary hack until we finish remaining work.
    ImGui.SameLine(0.0, 0.0); ImGui.Text(" (out %.2f)", ImGui.GetFontSize())
    ImGui.SameLine(); MetricsHelpMarker("- This is scaling font only. General scaling will come later.")
    style.FontScaleMain = ImGui.DragFloat("FontScaleMain", style.FontScaleMain, 0.02, 0.5, 4.0)
    style.FontScaleDpi = ImGui.DragFloat("FontScaleDpi", style.FontScaleDpi, 0.02, 0.5, 4.0)
    ImGui.BulletText("Load a nice font for better results!")
    ImGui.BulletText("Please submit feedback:")
    ImGui.SameLine(); ImGui.TextLinkOpenURL("#8465", "https://github.com/ocornut/imgui/issues/8465")
    ImGui.BulletText("Read FAQ for more details:")
    ImGui.SameLine(); ImGui.TextLinkOpenURL("dearimgui.com/faq", "https://www.dearimgui.com/faq/")

    ImGui.SeparatorText("Font List")
    local cfg = g.DebugMetricsConfig
    _, cfg.ShowFontPreview = ImGui.Checkbox("Show font preview", cfg.ShowFontPreview)
    -- Font loaders
    if ImGui.TreeNode("Loader", "Loader: '%s'", atlas.FontLoaderName or "NULL") then
        ImGui.BeginDisabled()
        ImGui.RadioButtonEx("stb_truetype", true)
        ImGui.SameLine()
        ImGui.RadioButtonEx("FreeType", false)
        ImGui.SetItemTooltip("Not available on Roblox.")
        ImGui.EndDisabled()
        ImGui.TreePop()
    end
    -- Font list
    for i, font in atlas.Fonts:iter() do
        ImGui.PushID(i)
        ImGui.DebugNodeFont(font)
        ImGui.PopID()
    end

    ImGui.SeparatorText("Font Atlas")
    if ImGui.Button("Compact") then atlas:CompactCache() end
    ImGui.SameLine()
    if ImGui.Button("Grow") then ImFontAtlasTextureGrow(atlas) end
    ImGui.SameLine()
    if ImGui.Button("Clear All") then ImFontAtlasBuildClear(atlas) end
    ImGui.SetItemTooltip("Destroy cache and custom rectangles.")
    for tex_n, tex in atlas.TexList:iter() do
        if tex_n > 1 then ImGui.SameLine() end
        ImGui.Text("Tex: %dx%d", tex.Width, tex.Height)
    end
    local b = atlas.Builder
    if b then
        local packed_sqrt = math.floor(math.sqrt(b.RectsPackedSurface or 0))
        local discarded_sqrt = math.floor(math.sqrt(b.RectsDiscardedSurface or 0))
        ImGui.Text("Packed rects: %d, area: about %d px ~%dx%d px", b.RectsPackedCount or 0, b.RectsPackedSurface or 0, packed_sqrt, packed_sqrt)
        ImGui.Text("incl. Discarded rects: %d, area: about %d px ~%dx%d px", b.RectsDiscardedCount or 0, b.RectsDiscardedSurface or 0, discarded_sqrt, discarded_sqrt)
    end
    -- Texture list
    -- (ensure the last texture always use the same ID, so we can keep it open neatly)
    for tex_n, tex in atlas.TexList:iter() do
        if tex_n == atlas.TexList.Size then ImGui.SetNextItemOpen(true, ImGuiCond.Once) end
        ImGui.DebugNodeTexture(tex, atlas.TexList.Size - tex_n, nil)
    end
end

